from z3 import *

# --- Enumerate worlds ---
World, (s0, s1, s2, s3) = EnumSort('World', ['s0', 's1', 's2', 's3'])

# --- Accessibility relation (transitions) ---
def trans(w1, w2):
    """Returns a constraint that (w1, w2) is in the accessibility relation."""
    return Or(
        And(w1 == s0, w2 == s1),
        And(w1 == s1, w2 == s2),
        And(w1 == s2, w2 == s3)
    )

# --- Atomic propositions ---
def arrays_generated(w):
    return Or(w == s1, w == s2, w == s3)

def matrix_initialized(w):
    return Or(w == s2, w == s3)

def function_defined(w):
    return w == s3

def sweep_computed(w):
    return w == s3

# --- Encode a counterexample search ---
# We look for a path of length 3 (steps s0→s1→s2→s3) that avoids sweep_computed.
# If unsatisfiable, then all paths eventually satisfy sweep_computed → property holds.

path_len = 3   # number of transitions
W = [Const(f'w_{i}', World) for i in range(path_len + 1)]  # states along the path

solver = Solver()

# Path must start at s0
solver.add(W[0] == s0)

# Transitions between consecutive states
for i in range(path_len):
    solver.add(trans(W[i], W[i+1]))

# Never visit a state where sweep_computed is true
for i in range(path_len + 1):
    solver.add(Not(sweep_computed(W[i])))

# Check for counterexample
result = solver.check()
if result == sat:
    print("Counterexample found: AF(sweep_computed) DOES NOT hold.")
    model = solver.model()
    for i in range(path_len + 1):
        print(f"  w_{i} = {model[W[i]]}")
elif result == unsat:
    print("No counterexample: AF(sweep_computed) holds (proved).")
else:
    print("Unknown")

